productDetailCustomCss:
.mg-page {
  --c1: #7C3AED;
  --c2: #F59E0B;
  --c3: #10B981;
  --c4: #EF4444;
  --c5: #0EA5E9;
  --c6: #EC4899;
  --text: #1F2937;
  --muted: #6B7280;
  --border: #E5E7EB;

  width: 100%;
  max-width: 1300px;
  margin: 0 auto;
  padding: 0 1.5rem;
  box-sizing: border-box;
  color: var(--text);
  font-family: inherit;
  line-height: 1.7;
  text-align: left;
}
.mg-page * { box-sizing: border-box; }
.mg-center { text-align: center; }


.mg-band {
  text-align: center;
  padding: 3.5rem 2rem;
  margin-top: 2.5rem;
  border-radius: 28px;
  background: #F5F3FF;
  border: 2px dashed #C4B5FD;
}
.mg-band-chip {
  display: inline-block;
  background: #7C3AED;
  color: #fff;
  padding: 0.45rem 1.1rem;
  border-radius: 999px;
  font-size: 13px;
  font-weight: 700;
  margin-bottom: 1.25rem;
}
.mg-band-title {
  font-size: 42px;
  font-weight: 900;
  margin-bottom: 1rem;
  color: #4C1D95;
}
.mg-band-sub {
  max-width: 640px;
  margin: 0 auto;
  font-size: 17px;
  color: var(--muted);
}


.mg-block { margin: 4rem 0; }
.mg-block-title {
  font-size: 26px;
  font-weight: 800;
  margin-bottom: 2rem;
}


.mg-feat-row {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1.25rem;
}
.mg-feat {
  border-radius: 18px;
  padding: 1.75rem;
  border: 1px solid var(--border);
  transition: transform 0.3s ease, box-shadow 0.3s ease;
}
.mg-feat:hover { transform: translateY(-6px); box-shadow: 0 14px 28px rgba(0,0,0,0.08); }
.mg-feat h3 { font-size: 17px; font-weight: 800; margin-bottom: 0.5rem; }
.mg-feat p { font-size: 14px; color: var(--muted); margin: 0; }
.mg-feat-icon {
  width: 50px; height: 50px;
  border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  font-size: 22px;
  margin-bottom: 1rem;
  background: #fff;
  border: 2px solid currentColor;
}
.mg-feat-a { background: #FAF5FF; color: var(--c1); }
.mg-feat-b { background: #FFFBEB; color: var(--c2); }
.mg-feat-c { background: #ECFDF5; color: var(--c3); }
.mg-feat-d { background: #FEF2F2; color: var(--c4); }
.mg-feat-e { background: #F0F9FF; color: var(--c5); }
.mg-feat-f { background: #FDF2F8; color: var(--c6); }
.mg-feat h3, .mg-feat p { color: var(--text); }


.mg-size-row {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 1.5rem;
  max-width: 620px;
}
.mg-size {
  border-radius: 20px;
  padding: 2rem;
  text-align: center;
  border: 2px solid var(--border);
}
.mg-size-1 { background: #EFF6FF; border-color: #BFDBFE; }
.mg-size-2 { background: #FFFBEB; border-color: #FDE68A; }
.mg-size-pill {
  display: inline-block;
  padding: 0.3rem 0.9rem;
  border-radius: 999px;
  font-size: 12px;
  font-weight: 700;
  text-transform: uppercase;
  background: #fff;
  margin-bottom: 0.75rem;
}
.mg-size-num { font-size: 40px; font-weight: 900; margin-bottom: 0.4rem; }
.mg-size-num span { font-size: 14px; font-weight: 600; color: var(--muted); margin-left: 0.3rem; }
.mg-size p { margin: 0; font-size: 14px; color: var(--muted); }


.mg-sheet {
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  gap: 2rem;
  background: #fff;
  border: 1px solid var(--border);
  border-radius: 22px;
  padding: 2.5rem;
}
.mg-sheet-divider { width: 1px; background: var(--border); }
.mg-sheet-col h3 { font-size: 19px; font-weight: 800; margin-bottom: 1.25rem; }
.mg-tick-row {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 0.55rem 0;
  font-size: 15px;
  border-bottom: 1px solid #F3F4F6;
}
.mg-tick-row:last-of-type { border-bottom: none; }
.mg-tick {
  width: 22px; height: 22px; flex-shrink: 0;
  border-radius: 50%;
  background: var(--c3);
  color: #fff;
  font-size: 12px;
  font-weight: 800;
  display: flex; align-items: center; justify-content: center;
}
.mg-tick-alt { background: var(--c2); }
.mg-note {
  margin-top: 1rem;
  font-size: 13px;
  color: var(--muted);
  background: #F9FAFB;
  border-radius: 10px;
  padding: 0.65rem 0.9rem;
}


.mg-safety {
  display: flex;
  align-items: center;
  gap: 1.25rem;
  background: #FEF2F2;
  border: 2px dashed #FCA5A5;
  border-radius: 20px;
  padding: 1.5rem 2rem;
}
.mg-safety-icon { font-size: 2.25rem; flex-shrink: 0; }
.mg-safety h4 { font-size: 16px; font-weight: 800; margin: 0 0 0.25rem; color: var(--c4); }
.mg-safety p { margin: 0; font-size: 14px; color: var(--muted); }


.mg-chip-row { display: flex; flex-wrap: wrap; justify-content: center; gap: 0.75rem; }
.mg-chip {
  padding: 0.6rem 1.2rem;
  border-radius: 999px;
  font-size: 14px;
  font-weight: 700;
  border: 2px solid transparent;
  transition: transform 0.25s ease;
}
.mg-chip:hover { transform: translateY(-3px); }
.mg-chip-1 { background: #F5F3FF; color: var(--c1); border-color: #DDD6FE; }
.mg-chip-2 { background: #FFFBEB; color: #B45309; border-color: #FDE68A; }
.mg-chip-3 { background: #ECFDF5; color: #047857; border-color: #A7F3D0; }
.mg-chip-4 { background: #FEF2F2; color: #B91C1C; border-color: #FECACA; }
.mg-chip-5 { background: #F0F9FF; color: #0369A1; border-color: #BAE6FD; }
.mg-chip-6 { background: #FDF2F8; color: #BE185D; border-color: #FBCFE8; }


.mg-closing {
  text-align: center;
  background: #4C1D95;
  color: #fff;
  border-radius: 24px;
  padding: 3.5rem 2rem;
  margin: 4rem 0 3rem;
}
.mg-closing h2 { font-size: 30px; font-weight: 900; margin-bottom: 1rem; }
.mg-closing p { max-width: 620px; margin: 0 auto; font-size: 16px; opacity: 0.9; }


@media (max-width: 900px) {
  .mg-feat-row { grid-template-columns: repeat(2, 1fr); }
  .mg-band-title { font-size: 32px; }
  .mg-sheet { grid-template-columns: 1fr; }
  .mg-sheet-divider { display: none; }
}
@media (max-width: 640px) {
  .mg-band { padding: 2.5rem 1.25rem; }
  .mg-band-title { font-size: 27px; }
  .mg-feat-row { grid-template-columns: 1fr; }
  .mg-size-row { grid-template-columns: 1fr; }
  .mg-closing h2 { font-size: 24px; }
}

