productDetailCustomCss:
.dr-detail-area {

  --dr-navy: #0f172a;       
  --dr-pink: #f43f5e;       
  --dr-yellow: #fbbf24;     
  --dr-sky: #0ea5e9;        
  --dr-gray: #f1f5f9;       
  --dr-text-muted: #64748b; 

  max-width: 1200px;
  margin: 0 auto;
  padding: 40px 15px;
  background-color: #ffffff;
  color: var(--dr-navy);
  font-family: 'Inter', -apple-system, sans-serif;
  line-height: 1.6;
}

.dr-detail-area * { box-sizing: border-box; }


.dr-intro-block {
  text-align: center;
  padding: 40px 0;
  border-bottom: 1.5px solid var(--dr-gray);
  margin-bottom: 50px;
}
.dr-tag-pill {
  display: inline-block;
  background: #fff1f2; 
  color: var(--dr-pink);
  font-weight: 800; font-size: 12px; padding: 6px 14px;
  border-radius: 50px; border: 1px solid rgba(244,63,94,0.15);
  margin-bottom: 20px;
}
.dr-main-heading { font-size: clamp(28px, 5vw, 42px); font-weight: 900; margin-bottom: 20px; color: var(--dr-navy); }
.dr-main-para { max-width: 850px; margin: 0 auto; font-size: 18px; color: var(--dr-text-muted); }


.dr-section { margin-bottom: 64px; }
.dr-center { text-align: center; }
.dr-sub-title { font-size: 26px; font-weight: 800; margin: 0 0 32px; color: var(--dr-navy); }
.dr-accent-bar { display: none; }


.dr-modes-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
}
.dr-mode-card {
  background: white; border: 1.5px solid var(--dr-gray);
  padding: 30px 26px; border-radius: 28px; transition: 0.3s;
  text-align: center;
  box-shadow: 0 6px 20px rgba(15, 23, 42, 0.04);
}
.dr-mode-card:hover { border-color: var(--dr-pink); transform: translateY(-5px); box-shadow: 0 14px 34px rgba(244,63,94,0.12); }
.dr-mode-icon {
  width: 64px; height: 64px; border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  font-size: 28px; margin: 0 auto 16px;
  background: linear-gradient(135deg, #fff1f2, #ffe4e6);
  border: 1.5px solid rgba(244, 63, 94, 0.15);
}
.dr-mode-card h4 { font-size: 19px; font-weight: 800; margin-bottom: 10px; color: var(--dr-pink); }
.dr-mode-card p { font-size: 14px; color: var(--dr-text-muted); margin: 0; }


.dr-stem-block {
  padding: 46px 40px; border-radius: 32px; border: 1.5px solid var(--dr-gray);
  text-align: center; background-image: radial-gradient(circle at bottom left, #f0f9ff 0%, #ffffff 50%); 
}
.dr-skill-pills { display: flex; flex-wrap: wrap; justify-content: center; gap: 10px; margin-top: 25px; }
.dr-sp-pill {
  padding: 8px 18px; border-radius: 50px; background: #fff;
  border: 1px solid var(--dr-gray); font-size: 13px; font-weight: 700; color: var(--dr-sky);
}


.dr-feature-white-box {
  background: #ffffff; border: 1.5px solid var(--dr-gray);
  border-radius: 28px; display: grid; grid-template-columns: 1fr 1px 1fr;
  overflow: hidden;
}
.dr-feature-list-col { padding: 40px; }
.dr-col-title { font-size: 20px; font-weight: 800; margin-bottom: 22px; color: var(--dr-navy); display: flex; align-items: center; gap: 8px; }
.dr-divider-line { background: var(--dr-gray); height: auto; }

.dr-check-items { list-style: none; padding: 0; margin: 0; }
.dr-check-items li { display: flex; gap: 12px; margin-bottom: 16px; font-size: 15px; color: var(--dr-text-muted); }
.dr-check-items li::before { content: "✓"; color: var(--dr-pink); font-weight: 900; }
.dr-check-items strong { color: var(--dr-navy); font-weight: 700; }

.dr-specs-list { list-style: none; padding: 0; margin: 0; }
.dr-specs-list li {
  display: flex; justify-content: space-between; border-bottom: 1px dashed var(--dr-gray);
  padding: 12px 0; font-size: 14px; font-weight: 600; color: var(--dr-navy);
}
.dr-specs-list li span { color: var(--dr-text-muted); font-weight: 500; }


.dr-safety-panel {
    background: #f0fdf4; 
    border-radius: 22px; padding: 28px;
    display: flex; align-items: flex-start; gap: 18px;
}
.dr-safety-icon {
  width: 56px; height: 56px; border-radius: 50%; flex-shrink: 0;
  display: flex; align-items: center; justify-content: center;
  font-size: 26px; background: #ffffff; border: 1.5px solid #bbf7d0;
}
.dr-safety-content h4 { color: #059669;  font-weight: 800; margin: 0 0 5px; }
.dr-safety-content p { font-size: 14.5px; color: var(--dr-text-muted); margin: 0; }


.dr-accent-center { margin-left: auto; margin-right: auto; }


.dr-steps-row {
  display: grid; grid-template-columns: repeat(4, 1fr); gap: 20px;
}
.dr-step {
  background: #f8fafc; border: 1.5px solid var(--dr-gray); border-radius: 24px;
  padding: 26px 22px; text-align: center;
}
.dr-step-num {
  width: 38px; height: 38px; border-radius: 50%; background: var(--dr-pink); color: #fff;
  display: flex; align-items: center; justify-content: center;
  font-weight: 900; font-size: 16px; margin: 0 auto 14px;
}
.dr-step h4 { font-size: 15.5px; font-weight: 800; margin-bottom: 8px; color: var(--dr-navy); }
.dr-step p { font-size: 13px; color: var(--dr-text-muted); margin: 0; }


.dr-care-grid {
  display: grid; grid-template-columns: repeat(4, 1fr); gap: 18px;
}
.dr-care-item {
  background: #fff; border: 1.5px solid var(--dr-gray); border-radius: 20px;
  padding: 22px; text-align: center;
}
.dr-care-icon {
  width: 48px; height: 48px; border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  font-size: 22px; margin: 0 auto 10px;
  background: #f0f9ff; border: 1.5px solid #dff2fe;
}
.dr-care-item p { font-size: 13px; color: var(--dr-text-muted); margin: 0; }


.dr-faq-list { max-width: 800px; margin: 0 auto; display: flex; flex-direction: column; gap: 12px; }
.dr-faq-item {
  border: 1.5px solid var(--dr-gray); border-radius: 18px; padding: 18px 22px;
  background: #fff; transition: 0.2s;
}
.dr-faq-item[open] { border-color: var(--dr-pink); background: #fff9fa; }
.dr-faq-item summary {
  cursor: pointer; font-weight: 700; font-size: 15px; color: var(--dr-navy);
  list-style: none; display: flex; justify-content: space-between; align-items: center;
}
.dr-faq-item summary::-webkit-details-marker { display: none; }
.dr-faq-item summary::after {
  content: "+"; font-size: 20px; color: var(--dr-pink); font-weight: 900; margin-left: 12px;
}
.dr-faq-item[open] summary::after { content: "−"; }
.dr-faq-item p { font-size: 14px; color: var(--dr-text-muted); margin: 12px 0 0; }


.dr-why-grid {
  display: grid; grid-template-columns: repeat(4, 1fr); gap: 18px;
}
.dr-why-item {
  text-align: center; padding: 24px 18px; border-radius: 20px;
  background: #f0f9ff; border: 1.5px solid #dff2fe;
}
.dr-why-icon {
  width: 52px; height: 52px; border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  font-size: 24px; margin: 0 auto 10px;
  background: #ffffff; border: 1.5px solid #dff2fe;
}
.dr-why-item h4 { font-size: 15px; font-weight: 800; margin-bottom: 6px; color: var(--dr-navy); }
.dr-why-item p { font-size: 12.5px; color: var(--dr-text-muted); margin: 0; }


.dr-unboxing-row { display: flex; flex-wrap: wrap; gap: 10px; justify-content: center; margin-top: 30px; }
.dr-unbox-item {
  background: white; border: 1px solid var(--dr-gray); padding: 14px 22px;
  border-radius: 14px; font-size: 14.5px; font-weight: 700; color: var(--dr-navy);
}


.dr-final-summary {
  background: linear-gradient(120deg, var(--dr-pink), #e11d48); 
  color: #fff; padding: 52px 36px;
  border-radius: 32px; text-align: center; margin-top: 32px;
}
.dr-final-summary h3 { font-size: 27px; font-weight: 900; margin-bottom: 14px; color: #ffffff; }
.dr-final-summary p { opacity: 0.95; font-size: 16.5px; max-width: 800px; margin: 0 auto; }


@media (max-width: 900px) {
  .dr-modes-grid { grid-template-columns: repeat(2, 1fr); }
  .dr-feature-white-box { grid-template-columns: 1fr; }
  .dr-divider-line { height: 1px; width: 100%; }
  .dr-steps-row { grid-template-columns: repeat(2, 1fr); }
  .dr-care-grid { grid-template-columns: repeat(2, 1fr); }
  .dr-why-grid { grid-template-columns: repeat(2, 1fr); }
}
@media (max-width: 600px) {
  .dr-detail-area { padding: 28px 4px; }
  .dr-intro-block { padding: 24px 6px; margin-bottom: 36px; }
  .dr-main-para { font-size: 16px; }
  .dr-section { margin-bottom: 44px; }
  .dr-sub-title { font-size: 22px; margin-bottom: 24px; }
  .dr-modes-grid { grid-template-columns: 1fr; }
  .dr-mode-card { padding: 26px 22px; }
  .dr-stem-block { padding: 30px 20px; }
  .dr-feature-list-col { padding: 28px 22px; }
  .dr-safety-panel { flex-direction: column; align-items: flex-start; text-align: left; }
  .dr-final-summary { padding: 40px 24px; border-radius: 26px; }
  .dr-final-summary h3 { font-size: 23px; }
  .dr-final-summary p { font-size: 15px; }
  .dr-steps-row { grid-template-columns: 1fr; }
  .dr-care-grid { grid-template-columns: 1fr; }
  .dr-why-grid { grid-template-columns: 1fr; }
  .dr-faq-item summary { font-size: 14px; }
}

