productDetailCustomCss:
.mf-product {
  font-family: 'Poppins', 'Segoe UI', sans-serif;
  color: #2b2b2b;
  width: 100%;
  max-width: 100%;
  margin: 0;
  padding: 20px 3%;
  box-sizing: border-box;
}

.mf-hero { text-align: center; margin-bottom: 28px; }

.mf-badge-new {
  display: inline-block;
  background: #000;
  color: #fff;
  padding: 6px 16px;
  border-radius: 20px;
  font-size: 13px;
  font-weight: 700;
  margin-bottom: 14px;
}

.mf-title {
  font-size: 28px;
  font-weight: 800;
  margin: 6px 0 10px;
  color: #d81f26;
}

.mf-shortdesc {
  max-width: 640px;
  margin: 0 auto 16px;
  font-size: 15px;
  line-height: 1.6;
  color: #444;
}

.mf-price-row {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  flex-wrap: wrap;
  margin-bottom: 16px;
}

.mf-price-old { text-decoration: line-through; color: #999; font-size: 16px; }
.mf-price-new { color: #d81f26; font-size: 22px; font-weight: 800; }
.mf-discount {
  background: #ffe4a1;
  color: #a15c00;
  padding: 3px 10px;
  border-radius: 12px;
  font-size: 12px;
  font-weight: 700;
}

.mf-color-row {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  margin-bottom: 24px;
  font-size: 13px;
  font-weight: 600;
  color: #444;
}

.mf-color-dot {
  width: 22px;
  height: 22px;
  border-radius: 50%;
  border: 2px solid #eee;
  display: inline-block;
}

.mf-color-white { background: #ffffff; box-shadow: inset 0 0 0 1px #ddd; }
.mf-color-black { background: #1a1a1a; }

.mf-quick-badges {
  display: flex;
  justify-content: center;
  gap: 18px;
  flex-wrap: wrap;
}

.mf-qbadge {
  display: flex;
  flex-direction: column;
  align-items: center;
  width: 100px;
  font-size: 11px;
  font-weight: 700;
  color: #333;
  text-align: center;
}

.mf-qcircle {
  width: 68px;
  height: 68px;
  border-radius: 50%;
  background: #f5f5f5;
  border: 1.5px solid #e5e5e5;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 10px;
  font-size: 28px;
}

.mf-intro-box {
  background: linear-gradient(135deg, #fff2e5, #ffe6ee);
  border-radius: 16px;
  padding: 26px;
  text-align: center;
  margin-bottom: 34px;
}

